import { createHash } from "node:crypto";
import { mkdir, readFile, writeFile } from "node:fs/promises";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const sqlEditorDir = dirname(fileURLToPath(import.meta.url));
const projectRoot = resolve(sqlEditorDir, "..", "..");
const bundles = [
  {
    output: "SINNER_PHASES_1_2_SQL_EDITOR.sql",
    title: "SINNER development database bootstrap: Phases 1 and 2",
    runNote: "Intended for a fresh Supabase development project. Run exactly once.",
    sources: [
      "supabase/migrations/20260907130000_core_foundation.sql",
      "supabase/migrations/20260907170000_spaces_marketplace.sql",
      "supabase/migrations/20260907210000_mexico_nationwide_locations.sql",
      "supabase/seed.sql",
      "supabase/sql-editor/verify_phase_1_2.sql",
    ],
  },
  {
    output: "SINNER_MEXICO_NATIONWIDE_UPGRADE.sql",
    title: "SINNER incremental upgrade: nationwide Mexico locations",
    runNote: "Intended for a development project that already has Phases 1 and 2. Run exactly once.",
    sources: [
      "supabase/migrations/20260907210000_mexico_nationwide_locations.sql",
      "supabase/seed.sql",
      "supabase/sql-editor/verify_phase_1_2.sql",
    ],
  },
];

async function buildBundle({ output, title, runNote, sources }) {
  const sections = await Promise.all(sources.map(async (source) => {
    const sql = (await readFile(resolve(projectRoot, source), "utf8")).trim();
    const digest = createHash("sha256").update(sql).digest("hex");

    return {
      source,
      sql,
      digest,
    };
  }));

  const manifest = sections
    .map(({ source, digest }) => `-- ${source} | sha256:${digest}`)
    .join("\n");

  const body = sections
    .map(
      ({ source, sql }, index) =>
        `\n-- ============================================================================\n-- ${index + 1}. SOURCE: ${source}\n-- ============================================================================\n\n${sql}\n`,
    )
    .join("");

  const bundle = `-- ${title}
-- GENERATED FILE. Do not edit this file directly.
-- Regenerate with: node supabase/sql-editor/build-bundle.mjs
-- ${runNote}
-- The transaction guarantees an all-or-nothing installation.
--
-- Source manifest:
${manifest}

begin;
${body}
commit;
`;

  const outputPath = resolve(sqlEditorDir, output);
  await writeFile(outputPath, bundle, "utf8");
  console.log(`Generated ${outputPath}`);
}

await mkdir(sqlEditorDir, { recursive: true });
for (const bundle of bundles) await buildBundle(bundle);

const phase3EnumSql = `-- SINNER Phase 3, Step 1.
-- Run this first in Supabase SQL Editor, then run SINNER_PHASE_3_BOOKING_ENGINE.sql.

do $$
begin
  alter type public.booking_status add value if not exists 'expired' after 'cancelled';
exception
  when duplicate_object then null;
end;
$$;
`;

const phase3EngineSql = await readFile(
  resolve(projectRoot, "supabase/migrations/20260907230000_booking_engine_phase_3.sql"),
  "utf8",
);

const phase3VerifySql = await readFile(resolve(sqlEditorDir, "verify_phase_3.sql"), "utf8");

await writeFile(
  resolve(sqlEditorDir, "SINNER_PHASE_3_STEP_1_ENUMS.sql"),
  phase3EnumSql,
  "utf8",
);

await writeFile(
  resolve(sqlEditorDir, "SINNER_PHASE_3_BOOKING_ENGINE.sql"),
  phase3EngineSql,
  "utf8",
);

await writeFile(
  resolve(sqlEditorDir, "SINNER_PHASE_3_DEMO_SEED.sql"),
  await readFile(resolve(projectRoot, "supabase/phase3_seed.sql"), "utf8"),
  "utf8",
);

await writeFile(
  resolve(sqlEditorDir, "SINNER_PHASE_3_REPAIR_AND_VERIFY.sql"),
  [
    `-- SINNER Phase 3 repair/retry SQL.
-- Use this after SINNER_PHASE_3_STEP_1_ENUMS.sql has run successfully.
-- Safe to rerun after a partial failed Phase 3 attempt: it uses IF NOT EXISTS,
-- CREATE OR REPLACE, DROP IF EXISTS, and idempotent grants/policies where possible.`,
    phase3EngineSql.trim(),
    `-- Verification.`,
    phase3VerifySql.trim(),
  ].join("\n\n"),
  "utf8",
);

const phase3OneSql = [
  `-- SINNER Phase 3 one-shot SQL.
-- Paste the full file into Supabase SQL Editor.
-- The COMMIT after Step 1 is intentional: PostgreSQL must commit a new enum value
-- before later statements can use that value in functions, constraints, or seed data.`,
  phase3EnumSql.trim(),
  "commit;",
  `-- Step 2: booking engine schema, RLS, policies, triggers, and RPCs.`,
  phase3EngineSql.trim(),
  `-- Step 3: verification.`,
  phase3VerifySql.trim(),
].join("\n\n");

await writeFile(resolve(sqlEditorDir, "SINNER_PHASE_3_ONE_SQL.sql"), phase3OneSql, "utf8");
